sys_script.script:
(function executeRule(current, previous) {
    var calc = new x_2298436_snackf_0.SnackFlowCalc()

    // DELTA ONLY, same arithmetic as SnackFlow Dispatch Stock Posting. 'dispatched_quantity'
    // is a running total on the line, so only the increment since the previous save will be
    // posted to the ledger, and only that increment needs to be covered by finished stock.
    var nowQty = calc.toNum(current.getValue('dispatched_quantity'))
    // On insert there is no 'previous' record, so the baseline is 0.
    var prevQty = previous ? calc.toNum(previous.getValue('dispatched_quantity')) : 0
    var delta = calc.round2(nowQty - prevQty)

    if (delta <= 0) {
        // Nothing newly dispatched. A downward correction posts nothing to the ledger, so
        // there is nothing to guard against here.
        return
    }

    var productId = current.getValue('product')
    if (!productId) {
        // No item to move; the posting rule will also no-op.
        return
    }

    // Current finished-goods balance from the ledger. No row is excluded because a sales
    // order line is not itself a ledger row.
    var available = calc.ledgerBalance('finished_product', productId, null)

    // Epsilon guards against decimal float noise on exactly-sufficient stock.
    if (available + 0.000001 < delta) {
        var productName = productId
        var prod = new GlideRecord('x_2298436_snackf_0_product')
        if (prod.get(productId)) {
            productName = prod.getValue('product_name') || productId
        }
        gs.addErrorMessage(
            'Cannot dispatch ' +
                delta +
                ' more packet(s) of ' +
                productName +
                ': only ' +
                available +
                ' in finished stock. Record a production receipt or a stock adjustment first, then re-enter the dispatch.',
        )
        // BEFORE rule, so aborting here rejects the sales line save itself. Nothing is
        // written to either the line or the ledger, which is the whole point: previously
        // the line saved and only the ledger posting was refused, leaving the two
        // inconsistent with the discrepancy visible only in the system log.
        current.setAbortAction(true)
    }
})(current, previous)
